FRAMES = [json.loads(line) for line in _PUBLIC_FRAMES_JSONL.splitlines()]


def canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def choose(policy, frame):
    view = copy.deepcopy(frame["view"])
    context = advanced_policy.build_context(view, worker.build_context(view), worker)
    with redirect_stdout(io.StringIO()):
        return worker.choose_action(frame["phase"], view, context, policy, advanced=True)


def observe_score_calls(candidate, original, operation):
    proxy = candidate.discard.__globals__["score"]
    proxy_code = type(proxy).compute_handScore.__code__
    raw_code = original.score.compute_handScore.__code__
    raw, capped = [], []
    caller_lines = []

    def profile(frame, event, result):
        if event == "return":
            if frame.f_code is raw_code and frame.f_back.f_code is proxy_code:
                raw.append(result)
            elif frame.f_code is proxy_code:
                capped.append(result)
                caller_lines.append(frame.f_back.f_lineno)

    previous = sys.getprofile()
    sys.setprofile(profile)
    try:
        result = operation()
    finally:
        sys.setprofile(previous)
    return result, raw, capped, caller_lines


class Cap8PolicyTests(unittest.TestCase):
    def setUp(self):
        self.original = advanced_policy.load_policy()
        self.original_bindings = dict(vars(self.original))
        self.score_bindings = dict(vars(self.original.score))
        self.candidate = cap8_policy.load_policy()

    def assert_original_bindings(self):
        for original, before in (
            (vars(self.original), self.original_bindings),
            (vars(self.original.score), self.score_bindings),
        ):
            self.assertEqual(set(original), set(before))
            for name, value in before.items():
                self.assertIs(original[name], value, name)

    def test_only_two_discard_functions_have_private_globals(self):
        for name, value in vars(self.original).items():
            if name not in {"discard", "select_a_card_to_discard"}:
                self.assertIs(getattr(self.candidate, name), value, name)
        for name, replaced in (("discard", "score"), ("select_a_card_to_discard", "discard")):
            old, new = getattr(self.original, name), getattr(self.candidate, name)
            self.assertIsNot(new, old)
            self.assertIs(new.__code__, old.__code__)
            self.assertIsNot(new.__globals__, old.__globals__)
            self.assertEqual(set(new.__globals__), set(old.__globals__))
            changed = [key for key in old.__globals__ if new.__globals__[key] is not old.__globals__[key]]
            self.assertEqual(changed, [replaced])
        self.assertIs(self.candidate.score, self.original.score)
        self.assertIs(self.candidate.select_a_card_to_discard.__globals__["discard"], self.candidate.discard)
        self.assert_original_bindings()

    def test_real_original_scores_at_or_below_eight_are_unchanged_and_larger_scores_cap(self):
        examples = [
            ([1, 2, 3, 4, 4, 5, 5, 6, 6, 19, 19, 20, 21, 22], [], 1),
            ([5, 5, 18, 18, 18, 20, 21, 22], FRAMES[3]["view"]["melds"], 2),
            ([2, 2, 4, 4, 4, 5, 6, 7], FRAMES[6]["view"]["melds"], 8),
            ([2, 2, 2, 4, 4, 4, 7, 7], FRAMES[6]["view"]["melds"], 16),
        ]
        proxy = self.candidate.discard.__globals__["score"]
        for hand, melds, expected in examples:
            with self.subTest(raw=expected):
                external = [worker.to_external(tile) for tile in hand]
                pile = [[worker.to_external(meld["tile"])] * (4 if meld["type"] == "kong" else 3) for meld in melds]
                before = copy.deepcopy((external, pile))
                self.assertEqual(self.original.score.compute_handScore(external, pile), expected)
                self.assertEqual(proxy.compute_handScore(external, pile), min(expected, 8))
                self.assertEqual(self.original.score.compute_handScore(external, pile), expected)
                self.assertEqual((external, pile), before)

    def test_eighteen_attributed_public_frames_keep_original_actions_and_alternate_without_pollution(self):
        self.assertEqual(len(FRAMES), 18)
        strategy_file = Path(self.original.__file__)
        self.assertEqual(hashlib.sha256(strategy_file.read_bytes()).hexdigest(), SOURCE_STRATEGY_SHA256)
        self.assertEqual(len(SOURCE_TRACES_SHA256), 64)
        clipped = unchanged = score_calls = 0
        for index, frame in enumerate(FRAMES):
            with self.subTest(frame=index, origin=frame["origin"]):
                view = frame["view"]
                self.assertEqual(hashlib.sha256(canonical(view).encode()).hexdigest(), frame["publicViewSha256"])
                for opponent in view["opponents"]:
                    self.assertNotIn("hand", opponent)
                for event in view["publicActions"]:
                    if event["kind"] == "draw":
                        self.assertEqual(set(event), {"seat", "kind"})
                before = canonical(view)
                self.assertEqual(choose(self.original, frame), frame["originalAction"])
                action, raw, capped, lines = observe_score_calls(
                    self.candidate, self.original, lambda: choose(self.candidate, frame)
                )
                self.assertEqual(len(raw), len(capped))
                self.assertEqual(capped, [min(value, 8) for value in raw])
                self.assertTrue(all(line == 459 for line in lines))
                score_calls += len(raw)
                clipped += sum(value > 8 for value in raw)
                unchanged += sum(value <= 8 for value in raw)
                # The strict worker validates every returned action. The
                # candidate may differ only when an actual discard was asked.
                if action["type"] != "discard" or frame["originalAction"]["type"] != "discard":
                    self.assertEqual(action, frame["originalAction"])
                self.assertEqual(choose(self.original, frame), frame["originalAction"])
                self.assertEqual(choose(self.candidate, frame), action)
                self.assertEqual(canonical(view), before)
                self.assert_original_bindings()
        self.assertEqual(score_calls, 14)
        self.assertEqual(clipped, 11)
        self.assertEqual(unchanged, 3)

    def test_controlled_dead_wait_hand_exercises_the_separate_theoretical_late_wall_path(self):
        # This is NOT an observed frame or a manufactured public history.
        # Use the fixed frame6 hand/pile as direct function input, exhaust its
        # possible completion tiles in a copied KB, and retain one wall tile.
        view = copy.deepcopy(FRAMES[6]["view"])
        context = advanced_policy.build_context(view, worker.build_context(view), worker)
        T, pile = context.player.hand, context.player.pile
        dc = context.player.daque_color
        knowledge = context.player.kgbase(context.dealer, context.players)
        theoretical = set()
        for discard in {tuple(item) for item in T}:
            for replacement in self.original.MJ():
                if replacement[0] != dc and self.original.hs.is_h_solx(
                    self.original.xreplace(T, list(discard), replacement), dc
                ):
                    theoretical.add(tuple(replacement))
        self.assertTrue(theoretical)
        for item in theoretical:
            knowledge[self.original.kbf(list(item))] = 0
        self.assertGreater(sum(knowledge), 1)
        self.assertGreater(self.original.hk.hyval(T, [meld[0] for meld in pile], knowledge, dc), 1)
        arguments = (T, pile, knowledge, context.player.get_dominant_color(), dc, 1, 2, [[0, 0, 0]] * 4, context.dealer.dqc)
        original_before = canonical(arguments)
        with redirect_stdout(io.StringIO()):
            original_action = self.original.discard(*copy.deepcopy(arguments))
            action, raw, capped, lines = observe_score_calls(
                self.candidate, self.original, lambda: self.candidate.discard(*copy.deepcopy(arguments))
            )
            self.assertEqual(self.original.discard(*copy.deepcopy(arguments)), original_action)
        self.assertTrue(raw)
        self.assertTrue(any(value > 8 for value in raw))
        self.assertEqual(set(lines), {417})
        self.assertEqual(capped, [min(value, 8) for value in raw])
        self.assertIn(action, T)
        self.assertEqual(canonical(arguments), original_before)
        self.assert_original_bindings()

    def test_repeated_loads_have_independent_clones_and_keep_original_action(self):
        second = cap8_policy.load_policy()
        self.assertIsNot(self.candidate.discard, second.discard)
        self.assertIsNot(self.candidate.discard.__globals__, second.discard.__globals__)
        self.assertIsNot(self.candidate.discard.__globals__["score"], second.discard.__globals__["score"])
        frame = FRAMES[6]
        a = choose(self.candidate, frame)
        self.assertEqual(choose(self.original, frame), frame["originalAction"])
        self.assertEqual(choose(second, frame), a)
        self.assertEqual(choose(self.candidate, frame), a)
        self.assert_original_bindings()

    def test_real_score_exception_is_not_replaced_by_a_value_or_fallback(self):
        proxy = self.candidate.discard.__globals__["score"]
        with self.assertRaises(TypeError):
            proxy.compute_handScore(None, [])
        self.assert_original_bindings()

    def test_upstream_loader_error_is_the_same_exception(self):
        failure = RuntimeError("upstream loader failed")
        with patch.object(advanced_policy, "load_policy", side_effect=failure):
            with self.assertRaises(RuntimeError) as caught:
                cap8_policy.load_policy()
        self.assertIs(caught.exception, failure)
        self.assert_original_bindings()

    def test_load_revalidates_real_closure_even_when_the_original_module_is_cached(self):
        with tempfile.TemporaryDirectory(prefix="cap8-provenance-") as directory:
            vendor = Path(directory) / "vendor"
            shutil.copytree(advanced_policy.VENDOR, vendor)
            source = vendor / "derived/ebony72_advanced_public/strategyz0614.py"
            source.write_bytes(source.read_bytes() + b"\n# altered copy\n")
            with patch.object(advanced_policy, "VENDOR", vendor):
                with self.assertRaisesRegex(ValueError, "Changed advanced-public source"):
                    cap8_policy.load_policy()
        self.assert_original_bindings()


if __name__ == "__main__":
    unittest.main()
